def tri(n):
    if n < 0:
        return []
    if n == 0:
        return [1]

    tribonacci = [1, 3]

    for i in range(2, n + 1):
        if i % 2 == 0:
            tribonacci.append(1 + i // 2)
        else:
            tribonacci.append(tribonacci[i - 1] + tribonacci[i - 2] + tribonacci[i])

    return tribonacci[:n + 1]

# Examples
print(tri(3))  # Output: [1, 3, 2, 8]
```

