def skjkasdkd(lst):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def largest_prime(lst):
        prime = None
        for num in lst:
            if is_prime(num) and (prime is None or num > prime):
                prime = num
        return prime

    prime = largest_prime(lst)
    if prime is not None:
        return sum(int(digit) for digit in str(prime))
    return 0

